import { createHook, executionAsyncId, triggerAsyncId, AsyncLocalStorage } from 'node:async_hooks';
const known = new Map<number, number>();
function label(id: number): string { const k = known.get(id); return k === undefined ? 'ext' : '#' + k; }
function trace(): { disable(): void } {
  return createHook({
    init(id: number, type: string, trigger: number): void { if (type === 'PROMISE') { known.set(id, known.size + 1); console.log('init', label(id), 'trig', label(trigger)); } },
    before(id: number): void { if (known.has(id)) { console.log('before', label(id)); } },
    after(id: number): void { if (known.has(id)) { console.log('after', label(id)); } },
    promiseResolve(id: number): void { if (known.has(id)) { console.log('resolve', label(id)); } },
  }).enable();
}
async function work(): Promise<void> { console.log('a'); await 1; console.log('b'); await new Promise<void>((resolve: () => void): void => { setTimeout(resolve, 1); }); console.log('c'); }
function main(): void { setTimeout((): void => { const hook = trace(); work(); setTimeout((): void => { console.log('timer'); }, 0); setTimeout((): void => { hook.disable(); }, 30); }, 0); }
